import React, { useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

// Fixe l'icône du marqueur par défaut pour réact-leaflet (correction bug d'import)
import icon from 'leaflet/dist/images/marker-icon.png';
import iconShadow from 'leaflet/dist/images/marker-shadow.png';
let DefaultIcon = L.icon({
  iconUrl: icon,
  shadowUrl: iconShadow,
  iconSize: [25, 41],
  iconAnchor: [12, 41],
});
L.Marker.prototype.options.icon = DefaultIcon;

interface ThreatPoint {
  id: string;
  src_ip: string;
  dst_ip: string;
  country: string;
  latitude: number;
  longitude: number;
  attack_count: number;
  severity: 'low' | 'medium' | 'high' | 'critical';
}

const ThreatMap: React.FC = () => {
  const [threats] = useState<ThreatPoint[]>([
    {
      id: 'threat1',
      src_ip: '203.45.67.89',
      dst_ip: '10.0.0.10',
      country: 'China',
      latitude: 39.9042,
      longitude: 116.4074,
      attack_count: 542,
      severity: 'critical'
    },
    // ... autres menaces
  ]);

  const [selectedThreat, setSelectedThreat] = useState<ThreatPoint | null>(null);

  // Centre initial de la carte (latitude, longitude)
  const centerPosition: [number, number] = [20, 0];

  // Générez un tableau de points de menace avec leurs coordonnées
  const threatMarkers = threats.map(threat => ({
    ...threat,
    position: [threat.latitude, threat.longitude] as [number, number],
  }));

  return (
    <div className="threat-map-container">
      <h1 className="page-title">Carte des Menaces</h1>

      <div className="threat-map-wrapper">
        <div className="threat-map">
          {/* Conteneur de la carte */}
          <MapContainer
            center={centerPosition}
            zoom={2}
            style={{ height: '500px', width: '100%' }}
          >
            {/* Fonds de carte (OpenStreetMap) */}
            <TileLayer
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            />

            {/* Marquage des menaces */}
            {threatMarkers.map(marker => (
              <Marker
                key={marker.id}
                position={marker.position}
                eventHandlers={{
                  click: () => {
                    setSelectedThreat(marker);
                  },
                }}
              >
                <Popup>
                  <div>
                    <strong>{marker.country}</strong><br />
                    IP source: {marker.src_ip}<br />
                    IP cible: {marker.dst_ip}<br />
                    Attaques: {marker.attack_count}<br />
                    Sévérité: {marker.severity}
                  </div>
                </Popup>
              </Marker>
            ))}

            {/* Optionnel : tracer des arcs entre sources et cibles */}
            {/* Pour chaque menace, vous pouvez tracer un arc entre (latSource, lngSource) et (latDest, lngDest) */}
          </MapContainer>
        </div>

        {/* Votre side-bar existante */}
        <div className="threat-sidebar">
          <h2>Menaces Détectées</h2>
          <div className="threats-list">
            {threats.map(threat => (
              <div
                key={threat.id}
                className={`threat-item ${selectedThreat?.id === threat.id ? 'active' : ''}`}
                onClick={() => setSelectedThreat(threat)}
              >
                <div className="threat-header">
                  <span className={`severity-badge ${threat.severity}`}>
                    {threat.severity}
                  </span>
                  <span className="threat-country">{threat.country}</span>
                </div>
                <div className="threat-details">
                  {/* ... détails ... */}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {selectedThreat && (
        <div className="threat-details-panel">
          <h2>Détails de la Menace</h2>
          <div className="details-grid">
            {/* ... détails ... */}
          </div>
        </div>
      )}
    </div>
  );
};

export default ThreatMap;
